import{_ as t,o as a,c as e,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const d="/bzygq/assets/d2ef40d384f14c8fb9348499c72fd38f.Qih-6gTH.png",l=JSON.parse('{"title":"MongoDB 复制集与读写关注","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/MongoDB/06-复制集与读写关注.md","filePath":"Java面试问题汇总/MongoDB/06-复制集与读写关注.md","lastUpdated":1788929995000}'),n={name:"Java面试问题汇总/MongoDB/06-复制集与读写关注.md"};function i(y,r,p,c,m,P){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="mongodb-复制集与读写关注" tabindex="-1">MongoDB 复制集与读写关注 <a class="header-anchor" href="#mongodb-复制集与读写关注" aria-label="Permalink to &quot;MongoDB 复制集与读写关注&quot;">​</a></h1><p>复制集是 MongoDB 面向高可用和数据冗余的核心机制。它把同一份数据保存在多个 mongod 节点上，让一个节点故障时，集群仍有机会选出新的主节点继续服务。理解复制集时，不能只停留在“主从复制”四个字上，还要说清楚 oplog、异步复制、选举、多数派、读写关注以及从库旧数据风险。</p><p>在面试中，MongoDB 复制集最常见的边界问题是：复制集解决高可用，不解决水平拆数据；默认复制是异步的，不代表所有节点时时一致；读从库可以分担读压力，但可能读到旧数据；majority 能提高可靠性，但会带来更高等待成本。</p><h2 id="一、复制集解决高可用-不是分片扩容" tabindex="-1">一、复制集解决高可用，不是分片扩容 <a class="header-anchor" href="#一、复制集解决高可用-不是分片扩容" aria-label="Permalink to &quot;一、复制集解决高可用，不是分片扩容&quot;">​</a></h2><p>一个复制集通常由一个 Primary 和多个 Secondary 组成。Primary 负责接收写请求，Secondary 复制 Primary 上已经发生的数据变更。客户端驱动会感知复制集拓扑，正常情况下把写入发送到 Primary；Primary 故障后，剩余成员通过选举产生新的 Primary。</p><p><img src="'+d+'" alt="images/mongodb-replica-shard-topology.png"></p><p>images/mongodb-replica-shard-topology.png</p><p>这张拓扑图里要区分两层概念：复制集负责把同一个分片或同一份数据复制到多个节点，重点是高可用和冗余；分片集群负责把不同数据分散到不同 Shard，重点是容量和吞吐的水平扩展。生产环境中，一个 Shard 往往本身又是一个复制集，所以两者经常组合使用，但解决的问题不同。</p><p>复制集的收益主要有三点。第一，Primary 宕机时可以自动选主，减少人工切换成本。第二，数据存在多个副本，单节点损坏不等于数据立刻丢失。第三，在能接受旧数据的场景下，可以把部分读取导向 Secondary，分担 Primary 压力。</p><p>复制集也有边界。它不会自动把一个超大集合拆到多台机器上，每个数据节点通常仍保存完整数据副本；写入默认仍集中到 Primary；Secondary 复制存在延迟；选举期间可能短暂不可写。如果问题是单集合容量或写入吞吐超过单复制集承载能力，就要讨论分片，而不是只增加 Secondary。</p><h2 id="二、primary、secondary-与-oplog-复制链路" tabindex="-1">二、Primary、Secondary 与 oplog 复制链路 <a class="header-anchor" href="#二、primary、secondary-与-oplog-复制链路" aria-label="Permalink to &quot;二、Primary、Secondary 与 oplog 复制链路&quot;">​</a></h2><p>复制集的写入链路可以分成三步。客户端把写请求发给 Primary；Primary 在本地应用写入，并把这次变更记录到 oplog；Secondary 持续拉取并重放 oplog，让自己的数据逐步追上 Primary。</p><p>oplog 是复制集内部的操作日志，保存在 local 数据库中。它按时间顺序记录数据变更，Secondary 不需要重新执行原始业务逻辑，只要按顺序应用这些变更即可。这个设计让复制过程相对稳定，也让新节点可以通过初始同步加 oplog 追赶加入复制集。</p><p>db.orders.insertOne( { orderNo: &quot;O20260630001&quot;, userId: 10086, status: &quot;PAID&quot;, amount: NumberDecimal(&quot;199.00&quot;), createdAt: ISODate(&quot;2026-06-30T10:00:00Z&quot;) } )</p><p>上面这次写入不会由应用直接发给每一个 Secondary。应用只面向复制集写入，Primary 完成本地写入后记录复制日志，Secondary 再从同步源持续复制。由于复制通常是异步推进，Primary 返回成功时，Secondary 未必都已经应用了这条变更。</p><p>异步复制带来两个直接影响。第一，Secondary 可能落后于 Primary，因此读从库可能读不到刚写入的数据。第二，如果 Primary 在变更复制到足够多节点之前故障，这部分写入在故障恢复时可能面临回滚风险。要降低这个风险，需要配合更强的 writeConcern，而不是单纯假设“写到 Primary 就万无一失”。</p><p>Secondary 也不一定都一样。有些节点可能用于跨机房灾备，有些节点可能设置较低优先级，有些节点承担分析查询或备份任务。不同节点的网络距离、硬件能力和复制延迟不同，都会影响读请求的新鲜度和整体可用性设计。</p><h2 id="三、选举、多数派与故障窗口" tabindex="-1">三、选举、多数派与故障窗口 <a class="header-anchor" href="#三、选举、多数派与故障窗口" aria-label="Permalink to &quot;三、选举、多数派与故障窗口&quot;">​</a></h2><p>复制集同一时间最多只有一个能够完成正常写入的 Primary。当前 Primary 不可达时，复制集成员会根据心跳和成员状态发起选举。只有获得多数投票支持的成员，才能成为新的 Primary。多数派机制的核心目的，是避免网络分区时多个节点同时对外接受写入，造成数据分裂。</p><p>以三个数据节点为例，多数派是两个节点。如果一个 Primary 和一个 Secondary 所在机房仍能互相通信，它们可以形成多数并选出 Primary；如果某个孤立节点单独存活，由于拿不到多数票，就不能自行成为 Primary 对外写入。这样牺牲了一部分分区情况下的可写性，换取更清晰的一致性边界。</p><p>选举不是零成本。故障被检测、成员互相投票、驱动重新发现新 Primary，都需要时间。这个窗口内，应用可能遇到短暂写失败、超时或需要重试。成熟的业务代码要把这类错误当成分布式系统的正常情况处理，关键写操作要有幂等键，避免重试造成重复下单、重复扣款或重复发消息。</p><p>多数派也和写入可靠性相关。如果一次写入只在旧 Primary 上成功，还没复制到多数节点，旧 Primary 就故障并被新的 Primary 替换，这次写入可能不在新主节点的数据历史里。恢复时，旧 Primary 重新加入复制集，可能需要回滚自己多出来的那部分写入，以重新跟随新 Primary。</p><p>这就是为什么重要写入通常会考虑 writeConcern: { w: &quot;majority&quot; }。它要求写入被多数数据承载投票成员确认后，才向客户端报告写关注成功。这样即使发生选举，新 Primary 更大概率包含这次写入，回滚风险显著降低。</p><h2 id="四、readpreference-从哪里读" tabindex="-1">四、readPreference：从哪里读 <a class="header-anchor" href="#四、readpreference-从哪里读" aria-label="Permalink to &quot;四、readPreference：从哪里读&quot;">​</a></h2><p>readPreference 决定读请求优先发送到哪个类型的节点。默认模式通常是 primary，也就是从 Primary 读取。这种方式最容易理解，尤其适合写后立刻读、强依赖最新状态的链路，例如支付后查询订单状态、提交资料后立刻查看审核记录。</p><p>如果配置为 secondary 或 secondaryPreferred，读请求可以转到 Secondary。这样能把一部分读压力从 Primary 移开，适合报表、后台查询、非关键列表、低实时性分析等场景。但它的代价是可能读到旧数据，因为 Secondary 复制进度可能落后。</p><p>spring: data: mongodb: uri: mongodb://app:secret@mongo1:27017,mongo2:27017,mongo3:27017/shop?replicaSet=rs0&amp;readPreference=secondaryPreferred</p><p>读从库不是免费的性能优化。假设用户刚支付订单，写入已经在 Primary 成功，但某个 Secondary 还没复制到这条变更。如果后续查询被路由到这个 Secondary，用户可能看到订单仍是待支付。这不是查询代码写错，而是读偏好和复制延迟共同造成的新鲜度问题。</p><p>常见读偏好可以这样理解：</p><table tabindex="0"><thead><tr><th>readPreference</th><th>含义</th><th>适合场景</th><th>风险</th></tr></thead><tbody><tr><td>primary</td><td>只读 Primary</td><td>写后立刻读、关键业务状态</td><td>Primary 读压力较大</td></tr><tr><td>primaryPreferred</td><td>优先 Primary，不可用时读 Secondary</td><td>读可用性优先于严格新鲜度</td><td>故障时可能读旧数据</td></tr><tr><td>secondary</td><td>只读 Secondary</td><td>离线分析、报表、备份类读取</td><td>可能落后，Primary 可用也不读它</td></tr><tr><td>secondaryPreferred</td><td>优先 Secondary，不可用时读 Primary</td><td>低实时性查询分流</td><td>数据新鲜度不稳定</td></tr><tr><td>nearest</td><td>按延迟选择较近节点</td><td>多地域低延迟读取</td><td>不代表最新数据</td></tr></tbody></table><p>面试里要特别强调：读从库只能用于业务允许旧数据的路径。它可以降低 Primary 读压力，但不能保证“刚写完马上能从从库读到”。如果业务需要读己之写，可以保持 Primary 读取，或使用因果一致会话等更明确的机制，而不是简单把读偏好改成 Secondary。</p><h2 id="五、readconcern-与-writeconcern-读写关注的边界" tabindex="-1">五、readConcern 与 writeConcern：读写关注的边界 <a class="header-anchor" href="#五、readconcern-与-writeconcern-读写关注的边界" aria-label="Permalink to &quot;五、readConcern 与 writeConcern：读写关注的边界&quot;">​</a></h2><p>writeConcern 回答“写入要被确认到什么程度才算成功”。w: 1 表示 Primary 本地确认后即可返回，延迟低，但写入还没有复制到其他节点时存在故障回滚风险。w: &quot;majority&quot; 表示多数节点确认后才算写关注成功，可靠性更好，但请求要等待更多复制确认。</p><p>db.orders.insertOne( { orderNo: &quot;O20260630002&quot;, userId: 10086, status: &quot;CREATED&quot; }, { writeConcern: { w: &quot;majority&quot;, wtimeout: 5000 } } )</p><p>这里的 wtimeout 表示最多等待写关注确认的时间。需要注意，写关注超时不一定代表 Primary 没有写入成功，它只表示在指定时间内没有拿到足够节点确认。应用处理这类结果时，要结合幂等键和后续查询确认最终状态，不能简单重试出重复业务记录。</p><p>readConcern 回答“读取什么一致性视图”。常见的 local 读取当前节点已经应用的数据，但这些数据不一定已经被多数节点确认，极端情况下可能回滚。majority 更强调读取多数提交的数据，避免读到未来可能回滚的内容。事务中还可能使用 snapshot，让一组读写在一致的时间点视图上执行。</p><p>readConcern 和 readPreference 不是一回事。readPreference 决定去哪个节点读，readConcern 决定这个读操作要求怎样的数据视图。读 Secondary 且使用 local，可能读到该 Secondary 当前已经应用但不够新的数据；读 Primary 且使用 majority，更关注读到多数确认过的数据，但仍要理解它和业务“实时最新”不是完全同一个概念。</p><p>三者可以合在一张表里记：</p><table tabindex="0"><thead><tr><th>参数</th><th>回答的问题</th><th>影响</th></tr></thead><tbody><tr><td>readPreference</td><td>从 Primary 读还是 Secondary 读</td><td>影响读压力分布和数据新鲜度</td></tr><tr><td>readConcern</td><td>读取什么一致性级别的数据</td><td>影响可见数据范围和一致性语义</td></tr><tr><td>writeConcern</td><td>写入等多少节点确认</td><td>影响可靠性、回滚风险和写延迟</td></tr></tbody></table><p>实际项目里，默认配置可以覆盖大部分普通读取，但关键链路要单独评估。例如支付、扣库存、创建订单这类写入更适合 majority 写关注；写后立刻展示状态的接口不宜随意读从库；后台统计可以接受读从库和一定复制延迟。</p><h2 id="六、majority-的可靠性与延迟取舍" tabindex="-1">六、majority 的可靠性与延迟取舍 <a class="header-anchor" href="#六、majority-的可靠性与延迟取舍" aria-label="Permalink to &quot;六、majority 的可靠性与延迟取舍&quot;">​</a></h2><p>majority 的直觉含义是多数派确认。对于写入来说，writeConcern: &quot;majority&quot; 能让写入在复制集多数节点上被确认后再返回成功，从而降低主节点故障后被回滚的概率。对于读取来说，readConcern: &quot;majority&quot; 倾向于只返回已经被多数节点确认的数据，避免读到可能回滚的数据。</p><p>它的收益是可靠性更强，边界更清晰。关键业务写入如果只用 w: 1，应用可能在 Primary 本地写成功后就继续执行后续逻辑，但这条写入还没来得及复制出去。一旦 Primary 随后故障并发生选举，业务层已经认为成功的数据可能在新 Primary 上不存在。使用 majority 后，这类风险会明显降低。</p><p>它的代价是延迟和可用性压力。写入需要等待更多成员确认，慢 Secondary、跨机房网络抖动、磁盘压力都会拉长写延迟；如果复制集无法形成多数，关键写入就不能正常拿到 majority 确认。系统选择 majority，本质是在“更可靠的提交边界”和“更低延迟、更高可用的返回”之间取舍。</p><p>可以按业务重要性分层：</p><table tabindex="0"><thead><tr><th>业务类型</th><th>推荐倾向</th><th>原因</th></tr></thead><tbody><tr><td>支付结果、订单状态、账户关键变更</td><td>writeConcern: &quot;majority&quot;，读路径谨慎读从库</td><td>降低回滚和旧读导致的业务错误</td></tr><tr><td>幂等消息、任务状态、可补偿操作</td><td>根据补偿能力选择</td><td>可通过重试、对账、补偿修复</td></tr><tr><td>访问日志、埋点、临时数据</td><td>可以接受较弱确认</td><td>价值较低，吞吐和成本更重要</td></tr><tr><td>后台报表、离线分析读取</td><td>可读 Secondary</td><td>通常允许一定延迟</td></tr></tbody></table><p>面试回答复制集时，可以用一段话串起来：</p><p>MongoDB 复制集由 Primary 和 Secondary 组成，写入默认进入 Primary，Primary 把变更写入 oplog，Secondary 异步拉取并重放 oplog。Primary 故障时，复制集通过多数派选举产生新的 Primary，选举期间可能短暂不可写。因为复制是异步的，所以读 Secondary 可能读到旧数据，未复制到多数节点的写入也可能在故障后回滚。readPreference 决定从哪个节点读，readConcern 决定读什么一致性视图，writeConcern 决定写入等多少节点确认。关键写入通常用 majority 提高可靠性，但代价是延迟上升；低实时性读取可以读从库，但要接受旧数据风险。</p><p>最后要把复制集和分片边界说清楚。复制集不是为了让小查询更快，也不是为了把一个集合拆成多份；它主要解决节点故障、自动接管和数据冗余。分片才负责把数据按分片键分布到多个 Shard 上。把这两个概念分开，才能在架构题里判断问题到底是高可用、一致性，还是容量和吞吐扩展。</p>',49)])])}const s=t(n,[["render",i]]);export{l as __pageData,s as default};
